files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --btn-bg: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-active: #0a2647;
  --success: #4ecca3;
  --focus: #f5c518;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 30%, #23234a, var(--bg));
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border: 2px solid #2a2a5a;
  border-radius: 16px;
  padding: 32px 28px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 1px;
  margin-bottom: 8px;
  color: var(--accent);
  text-transform: uppercase;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--muted);
  margin-bottom: 28px;
}

.dials {
  display: flex;
  justify-content: center;
  gap: 18px;
  margin-bottom: 28px;
}

.dial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.value {
  font-size: 2.4rem;
  font-weight: 700;
  width: 64px;
  height: 64px;
  line-height: 64px;
  background: #0b1a30;
  border: 2px solid var(--btn-bg);
  border-radius: 10px;
  color: var(--success);
  font-variant-numeric: tabular-nums;
  user-select: none;
}

.btn {
  font-size: 1rem;
  width: 64px;
  height: 40px;
  border: 2px solid var(--btn-bg);
  border-radius: 8px;
  background: var(--btn-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, border-color 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.btn:hover {
  background: var(--btn-hover);
  border-color: var(--accent);
}

.btn:active {
  background: var(--btn-active);
  transform: scale(0.94);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.open-btn {
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 14px 48px;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
  margin-bottom: 20px;
}

.open-btn:hover {
  background: var(--accent-hover);
}

.open-btn:active {
  transform: scale(0.96);
}

.open-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.attempts {
  font-size: 0.95rem;
  color: var(--muted);
  margin-bottom: 12px;
}

.message {
  font-size: 1.1rem;
  font-weight: 600;
  min-height: 1.5em;
}

.message.success {
  color: var(--success);
}

.message.fail {
  color: var(--accent);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .dials {
    gap: 10px;
  }
  .value, .btn {
    width: 54px;
  }
  .value {
    height: 54px;
    line-height: 54px;
    font-size: 2rem;
  }
  .open-btn {
    padding: 12px 36px;
  }
}

(function () {
  'use strict';

  var dials = [0, 0, 0];
  var target = [3, 7, 2];
  var failCount = 0;
  var solved = false;

  var valueEls = [
    document.getElementById('dial-0'),
    document.getElementById('dial-1'),
    document.getElementById('dial-2')
  ];
  var failEl = document.getElementById('fail-count');
  var messageEl = document.getElementById('message');
  var openBtn = document.getElementById('open-btn');

  function render() {
    for (var i = 0; i < 3; i++) {
      valueEls[i].textContent = dials[i];
    }
  }

  function setMessage(text, type) {
    messageEl.textContent = text;
    messageEl.className = 'message' + (type ? ' ' + type : '');
  }

  function changeDial(index, delta) {
    if (solved) return;
    dials[index] = (dials[index] + delta + 10) % 10;
    render();
    setMessage('', '');
  }

  function attemptOpen() {
    if (solved) return;
    var match = dials[0] === target[0] &&
                dials[1] === target[1] &&
                dials[2] === target[2];
    if (match) {
      solved = true;
      setMessage('Unlocked! The lock opens.', 'success');
      openBtn.textContent = 'Opened';
      openBtn.disabled = true;
      openBtn.style.opacity = '0.6';
      openBtn.style.cursor = 'default';
    } else {
      failCount++;
      failEl.textContent = failCount;
      setMessage('Wrong combination. Try again.', 'fail');
    }
  }

  var dialContainers = document.querySelectorAll('.dial');
  dialContainers.forEach(function (container) {
    var index = parseInt(container.getAttribute('data-index'), 10);
    var upBtn = container.querySelector('.up');
    var downBtn = container.querySelector('.down');
    upBtn.addEventListener('click', function () { changeDial(index, 1); });
    downBtn.addEventListener('click', function () { changeDial(index, -1); });
  });

  openBtn.addEventListener('click', attemptOpen);

  render();
})();
